def make_equal(nums, cost1, cost2):
    """
    Given an integer array nums and two integers cost1 and cost2, return the minimum cost required to make all elements in the array equal.
    Since the answer may be very large, return it modulo 10^9 + 7.
    """
    total_cost = 0
    for i in range(len(nums)):
        if nums[i] == cost1:
            total_cost += 1
        elif nums[i] == cost2:
            total_cost += 2
        else:
            total_cost += cost1 + cost2
    return total_cost % 10**9 + 7

